  ["Arrow Volley"] = "Arrow Volley",

  ["Arrows apply poison to the target."] = "Mũi tên áp dụng chất độc vào mục tiêu.",

  ["Arrows shot ricochet {b.towers.ranger.skill_c.max_bounces[1]} times between enemies near the main target, each dealing {b.towers.ranger.skill_c.bounce_damage_mult[1]}% of the previous hit's damage."] = "Các mũi tên bắn nảy {b.towers.ranger.skill_c.max_bounces[1]} nhiều lần giữa các kẻ địch ở gần mục tiêu chính, mỗi mũi tên gây ra {b.towers.ranger.skill_c.bounce_damage_mult[1]}% sát thương của đòn đánh trước đó.",

  ["Arrows shot ricochet {b.towers.ranger.skill_c.max_bounces[2]} times between enemies near the main target, each dealing {b.towers.ranger.skill_c.bounce_damage_mult[2]}% of the previous hit's damage."] = "Các mũi tên bắn nảy {b.towers.ranger.skill_c.max_bounces[2]} nhiều lần giữa các kẻ địch ở gần mục tiêu chính, mỗi mũi tên gây ra {b.towers.ranger.skill_c.bounce_damage_mult[2]}% sát thương của đòn đánh trước đó.",

  ["Arrows shot ricochet {b.towers.ranger.skill_c.max_bounces[3]} times between enemies near the main target, each dealing {b.towers.ranger.skill_c.bounce_damage_mult[3]}% of the previous hit's damage."] = "Các mũi tên bắn nảy {b.towers.ranger.skill_c.max_bounces[3]} nhiều lần giữa các kẻ địch ở gần mục tiêu chính, mỗi mũi tên gây ra {b.towers.ranger.skill_c.bounce_damage_mult[3]}% sát thương của đòn đánh trước đó.",

