  ["Changi"] = "Changi",

  ["Channeling corrupt magic through the crystals embedded on their arms, the Shacklers are fearsome foes in close quarters."] = "Truyền ma thuật hư hỏng thông qua các tinh thể gắn trên cánh tay của họ, Shackler là kẻ địch đáng sợ trong khoảng cách gần.",

  ["Channeling his divine energy, Saitam gains 3 life regeneration per second."] = "Truyền năng lượng thần thánh của mình, Saitam nhận được 3 lần hồi sinh mỗi giây.",

  ["Channeling his divine energy, Saitam gains 6 life regeneration per second."] = "Truyền năng lượng thần thánh của mình, Saitam nhận được 6 lần hồi sinh mỗi giây.",

  ["Channeling his divine energy, Saitam gains 9 life regeneration per second."] = "Truyền năng lượng thần thánh của mình, Saitam nhận được 9 lần hồi sinh mỗi giây.",

  ["Channels his power to smite a single enemy, dealing {b.heroes.hero_oni.skill_a.damage_min}-{b.heroes.hero_oni.skill_a.damage_max} true damage."] = "Truyền sức mạnh của mình để hạ gục một kẻ địch, gây sát thương chuẩn {b.heroes.hero_oni.skill_a.damage_min}-{b.heroes.hero_oni.skill_a.damage_max}.",

  ["Channels his power to smite a single enemy, dealing {b.heroes.hero_oni.upgrades.upg_sa1.damage_min}-{b.heroes.hero_oni.upgrades.upg_sa1.damage_max} true damage."] = "Truyền sức mạnh của mình để hạ gục một kẻ địch, gây sát thương chuẩn {b.heroes.hero_oni.upgrades.upg_sa1.damage_min}-{b.heroes.hero_oni.upgrades.upg_sa1.damage_max}.",

  ["Channels his power to smite a single enemy, dealing {b.heroes.hero_oni.upgrades.upg_sa2.damage_min}-{b.heroes.hero_oni.upgrades.upg_sa2.damage_max} true damage."] = "Truyền sức mạnh của mình để hạ gục một kẻ địch, gây sát thương chuẩn {b.heroes.hero_oni.upgrades.upg_sa2.damage_min}-{b.heroes.hero_oni.upgrades.upg_sa2.damage_max}.",

