  ["Grabs an enemy of 200 life or less and flings it out of the stage. Home run!"] = "Tóm lấy kẻ địch có 200 mạng sống trở xuống và ném nó ra khỏi sân khấu. Chạy về nhà!",

  ["Grabs an enemy of 500 life or less and flings it out of the stage. Home run!"] = "Tóm lấy kẻ địch có 500 mạng sống trở xuống và ném nó ra khỏi sân khấu. Chạy về nhà!",

  ["Grabs any enemy and flings it out of the stage. Home run!"] = "Tóm lấy bất kỳ kẻ địch nào và ném nó ra khỏi sân khấu. Chạy về nhà!",

  ["Graceful and stylish, these warriors were chosen by their princess and are willing to die for her."] = "Duyên dáng và phong cách, những chiến binh này được công chúa của họ lựa chọn và sẵn sàng chết vì cô.",

  ["Grand Finale"] = "Grand Finale",

  ["Grants Cronan instant regeneration of 3 life per second."] = "Cho Cronan tái sinh ngay lập tức 3 mạng sống mỗi giây.",

  ["Grants Cronan instant regeneration of 6 life per second."] = "Cho Cronan khả năng hồi phục ngay lập tức 6 mạng sống mỗi giây.",

  ["Grants Cronan instant regeneration of 9 life per second."] = "Cho Cronan khả năng hồi phục ngay lập tức 9 mạng sống mỗi giây.",

  ["Grants Dierdre a heavenly armor to protect her from physical attacks."] = "Cấp cho Dierdre một bộ giáp thiên đường để bảo vệ cô khỏi các cuộc tấn công vật lý.",

  ["Grants Karkinos the ability to travel 60% faster below ground."] = "Giúp Karkinos di chuyển nhanh hơn 60% dưới lòng đất.",

  ["Grants a {b.towers.wizard.skill_b.s_damage_factor[1]}% damage buff to all nearby towers for {b.towers.wizard.skill_b.duration[1]} seconds."] = "Tăng {b.towers.wizard.skill_b.s_damage_factor[1]}% sát thương cho tất cả các tòa tháp gần đó trong {b.towers.wizard.skill_b.duration[1]} giây.",

  ["Grants a {b.towers.wizard.skill_b.s_damage_factor[2]}% damage buff to all nearby towers for {b.towers.wizard.skill_b.duration[2]} seconds."] = "Tăng {b.towers.wizard.skill_b.s_damage_factor[2]}% sát thương cho tất cả các tòa tháp gần đó trong {b.towers.wizard.skill_b.duration[2]} giây.",

  ["Grants a {b.towers.wizard.skill_b.s_damage_factor[3]}% damage buff to all nearby towers for {b.towers.wizard.skill_b.duration[3]} seconds."] = "Tăng {b.towers.wizard.skill_b.s_damage_factor[3]}% sát thương cho tất cả các tòa tháp gần đó trong {b.towers.wizard.skill_b.duration[3]} giây.",

  ["Grants allied units a %$heroes.hero_lumenir.shield.armor[1]%$% armor shield that reflects %$heroes.hero_lumenir.shield.spiked_armor[1]%$% damage back at enemies."] = "Cấp cho các đơn vị đồng minh một lá chắn giáp %$heroes.hero_lumenir.shield.armor[1]%$% phản ánh sát thương %$heroes.hero_lumenir.shield.spiked_armor[1]%$% lên kẻ địch.",

  ["Grants allied units a %$heroes.hero_lumenir.shield.armor[2]%$% armor shield that reflects %$heroes.hero_lumenir.shield.spiked_armor[2]%$% damage back at enemies."] = "Cấp cho các đơn vị đồng minh một lá chắn giáp %$heroes.hero_lumenir.shield.armor[2]%$% phản ánh sát thương %$heroes.hero_lumenir.shield.spiked_armor[2]%$% lên kẻ địch.",

  ["Grants allied units a %$heroes.hero_lumenir.shield.armor[3]%$% armor shield that reflects %$heroes.hero_lumenir.shield.spiked_armor[3]%$% damage back at enemies."] = "Cấp cho các đơn vị đồng minh một lá chắn giáp %$heroes.hero_lumenir.shield.armor[3]%$% phản ánh sát thương %$heroes.hero_lumenir.shield.spiked_armor[3]%$% lên kẻ địch.",

  ["Grants extra gold at the start of the stage."] = "Nhận thêm vàng khi bắt đầu màn chơi.",

  ["Grants {b.specials.towers.stage_14_blacksmith.skill_a.aura.armor_factor[1]}% extra armor and {b.specials.towers.stage_14_blacksmith.skill_a.aura.s_dmg_factor[1]}% extra damage to nearby units."] = "Tăng thêm giáp cho {b.specials.towers.stage_14_blacksmith.skill_a.aura.armor_factor[1]}% và tăng thêm sát thương {b.specials.towers.stage_14_blacksmith.skill_a.aura.s_dmg_factor[1]}% cho các đơn vị ở gần.",

  ["Grants {b.specials.towers.stage_14_blacksmith.skill_a.aura.armor_factor[2]}% extra armor and {b.specials.towers.stage_14_blacksmith.skill_a.aura.s_dmg_factor[2]}% extra damage to nearby units."] = "Tăng thêm giáp cho {b.specials.towers.stage_14_blacksmith.skill_a.aura.armor_factor[2]}% và tăng thêm sát thương {b.specials.towers.stage_14_blacksmith.skill_a.aura.s_dmg_factor[2]}% cho các đơn vị ở gần.",

  ["Grants {b.specials.towers.stage_14_blacksmith.skill_a.aura.armor_factor[3]}% extra armor and {b.specials.towers.stage_14_blacksmith.skill_a.aura.s_dmg_factor[3]}% extra damage to nearby units."] = "Tăng thêm giáp cho {b.specials.towers.stage_14_blacksmith.skill_a.aura.armor_factor[3]}% và tăng thêm sát thương {b.specials.towers.stage_14_blacksmith.skill_a.aura.s_dmg_factor[3]}% cho các đơn vị ở gần.",

