  ["Send wave"] = "Gửi đợt",

  ["Sends an automated mining drill towards an enemy, reducing it to a mound of gibs!"] = "Gửi một mũi khoan khai thác tự động về phía kẻ địch, biến nó thành một đống gib!",

  ["Sends forth 12 boom-bunnies that explode on contact dealing 30 area damage each."] = "Gửi ra 12 con thỏ bùng nổ khi tiếp xúc, gây sát thương 30 vùng cho mỗi con.",

  ["Sends forth 2 pixies to strike nearby enemies for 10 to 30 magic damage each."] = "Gửi 2 tiểu tiên tấn công kẻ địch ở gần, mỗi tiểu tiên gây 10 đến 30 sát thương phép.",

  ["Sends forth 2 shadows to strike nearby enemies for 24 damage each."] = "Gửi ra 2 cái bóng để tấn công kẻ địch ở gần, mỗi cái gây 24 sát thương.",

  ["Sends forth 3 pixies to strike nearby enemies for 12 to 40 magic damage each."] = "Gửi 3 tiểu tiên để tấn công kẻ địch ở gần, mỗi tiểu tiên gây 12 đến 40 sát thương phép.",

  ["Sends forth 3 shadows to strike nearby enemies for 32 damage each."] = "Gửi ra 3 cái bóng để tấn công kẻ địch ở gần, mỗi cái gây 32 sát thương.",

  ["Sends forth 4 boom-bunnies that explode on contact dealing 30 area damage each."] = "Gửi ra 4 con thỏ bùng nổ khi tiếp xúc, gây sát thương 30 vùng cho mỗi con.",

  ["Sends forth 4 pixies to strike nearby enemies for 18 to 50 magic damage each."] = "Gửi 4 tiểu tiên để tấn công kẻ địch ở gần, mỗi tiểu tiên gây từ 18 đến 50 sát thương phép.",

  ["Sends forth 4 shadows to strike nearby enemies for 40 damage each."] = "Gửi ra 4 cái bóng để tấn công kẻ địch ở gần, mỗi cái có 40 điểm sát thương.",

  ["Sends forth 8 boom-bunnies that explode on contact dealing 30 area damage each."] = "Gửi ra 8 con thỏ bùng nổ khi tiếp xúc, gây sát thương 30 vùng cho mỗi con.",

  ["Sends out a cloud of hot smoke that slows enemies by 30% for 3 seconds."] = "Tạo ra một đám khói nóng làm chậm kẻ địch 30% trong 3 giây.",

  ["Sends out a cloud of hot smoke that slows enemies by 40% for 4 seconds."] = "Tạo ra một đám khói nóng làm chậm kẻ địch 40% trong 4 giây.",

  ["Sends out a cloud of hot smoke that slows enemies by 50% for 5 seconds."] = "Tạo ra một đám khói nóng làm chậm kẻ địch đi 50% trong 5 giây.",

  ["Sends out a cloud of searing smoke that burns and slows enemies."] = "Tạo ra một đám khói thiêu đốt đốt cháy và làm chậm kẻ địch.",

  ["Sentinel Arbor"] = "Sentinel Arbor",

  ["Sentinels not only have the best bows and arrows, but they also come in threes!"] = "Lính canh không chỉ có cung tên tốt nhất mà còn có ba mũi tên!",

