  ["Shock and Awe"] = "Shock and Awe",

  ["Shocking Impact"] = "Shocking Impact",

  ["Shoot 100 Missiles."] = "Bắn 100 tên lửa.",

  ["Shoot one cannon dealing 60 to 120 damage."] = "Bắn một khẩu pháo gây sát thương từ 60 đến 120.",

  ["Shoot three cannons dealing 60 to 120 damage each. Devastating!"] = "Bắn ba khẩu pháo, mỗi khẩu có lực sát thương từ 60 đến 120. Tàn phá!",

  ["Shoot two cannons dealing 60 to 120 damage each."] = "Bắn hai khẩu pháo, mỗi khẩu có lực sát thương từ 60 đến 120.",

  ["Shoots 2 fire missiles from her burning heart, each dealing 30 to 55 damage."] = "Bắn 2 tên lửa từ trái tim đang cháy của cô ấy, mỗi tên gây sát thương từ 30 đến 55.",

  ["Shoots 2 fireballs that deal 20 to 40 area damage."] = "Bắn 2 quả cầu lửa gây sát thương diện tích từ 20 đến 40.",

  ["Shoots 2 projectiles at the same time, dealing {b.towers.archers.skill_a.damage_min[1]}-{b.towers.archers.skill_a.damage_max[1]} physical damage and stunning targets for {b.towers.archers.skill_a.stun_duration[1]} seconds."] = "Bắn 2 viên đạn cùng lúc, gây sát thương vật lý {b.towers.archers.skill_a.damage_min[1]}-{b.towers.archers.skill_a.damage_max[1]} và làm choáng mục tiêu trong {b.towers.archers.skill_a.stun_duration[1]} giây.",

  ["Shoots 2 projectiles at the same time, dealing {b.towers.archers.skill_a.damage_min[2]}-{b.towers.archers.skill_a.damage_max[2]} physical damage and stunning targets for {b.towers.archers.skill_a.stun_duration[2]} seconds."] = "Bắn 2 viên đạn cùng lúc, gây sát thương vật lý {b.towers.archers.skill_a.damage_min[2]}-{b.towers.archers.skill_a.damage_max[2]} và làm choáng mục tiêu trong {b.towers.archers.skill_a.stun_duration[2]} giây.",

  ["Shoots 2 projectiles at the same time, dealing {b.towers.archers.skill_a.damage_min[3]}-{b.towers.archers.skill_a.damage_max[3]} physical damage and stunning targets for {b.towers.archers.skill_a.stun_duration[3]} seconds."] = "Bắn 2 viên đạn cùng lúc, gây sát thương vật lý {b.towers.archers.skill_a.damage_min[3]}-{b.towers.archers.skill_a.damage_max[3]} và làm choáng mục tiêu trong {b.towers.archers.skill_a.stun_duration[3]} giây.",

  ["Shoots 3 bombs that deal {b.heroes.hero_bolin.skill_a.damage_min}-{b.heroes.hero_bolin.skill_a.damage_max} physical damage each and cover the area with smoke, slowing enemies that pass through."] = "Bắn 3 quả bom, mỗi quả gây sát thương vật lý {b.heroes.hero_bolin.skill_a.damage_min}-{b.heroes.hero_bolin.skill_a.damage_max} và bao phủ khu vực bằng khói, làm chậm kẻ địch đi qua.",

  ["Shoots 3 bombs that deal {b.heroes.hero_bolin.upgrades.upg_sa1.min_damage}-{b.heroes.hero_bolin.upgrades.upg_sa1.max_damage} physical damage each and cover the area with smoke, slowing enemies that pass through."] = "Bắn 3 quả bom, mỗi quả gây sát thương vật lý {b.heroes.hero_bolin.upgrades.upg_sa1.min_damage}-{b.heroes.hero_bolin.upgrades.upg_sa1.max_damage} và bao phủ khu vực bằng khói, làm chậm kẻ địch đi qua.",

  ["Shoots 3 bombs that deal {b.heroes.hero_bolin.upgrades.upg_sa2.min_damage}-{b.heroes.hero_bolin.upgrades.upg_sa2.max_damage} physical damage each and cover the area with smoke, slowing enemies that pass through."] = "Bắn 3 quả bom, mỗi quả gây sát thương vật lý {b.heroes.hero_bolin.upgrades.upg_sa2.min_damage}-{b.heroes.hero_bolin.upgrades.upg_sa2.max_damage} và bao phủ khu vực bằng khói, làm chậm kẻ địch đi qua.",

  ["Shoots 3 fire missiles from her burning heart, each dealing 40 to 70 damage."] = "Bắn 3 tên lửa từ trái tim đang cháy của cô ấy, mỗi tên lửa gây sát thương từ 40 đến 70.",

  ["Shoots 4 fire missiles from her burning heart, each dealing 45 to 80 damage."] = "Bắn 4 tên lửa từ trái tim rực cháy của cô, mỗi tên gây sát thương 45 đến 80.",

  ["Shoots 4 fireballs that deal 20 to 40 area damage."] = "Bắn 4 quả cầu lửa gây sát thương diện tích từ 20 đến 40.",

