  ["Sneezes dealing {b.towers.tree.skill_a.blind.s_damage[1]} true damage to nearby enemies in an area over the course of {b.towers.tree.skill_a.blind.duration[1]} seconds, also reducing their damage by {b.towers.tree.skill_a.blind.s_damage_factor}% for {b.towers.tree.skill_a.blind.duration[1]} seconds."] = "Hắt hơi, gây sát thương chuẩn {b.towers.tree.skill_a.blind.s_damage[1]} cho kẻ địch ở gần trong một khu vực trong thời gian {b.towers.tree.skill_a.blind.duration[1]} giây, đồng thời giảm sát thương của chúng đi {b.towers.tree.skill_a.blind.s_damage_factor}% trong {b.towers.tree.skill_a.blind.duration[1]} giây.",

  ["Sneezes dealing {b.towers.tree.skill_a.blind.s_damage[2]} true damage to nearby enemies in an area over the course of {b.towers.tree.skill_a.blind.duration[2]} seconds, also reducing their damage by {b.towers.tree.skill_a.blind.s_damage_factor}% for {b.towers.tree.skill_a.blind.duration[2]} seconds."] = "Hắt hơi, gây sát thương chuẩn {b.towers.tree.skill_a.blind.s_damage[2]} cho kẻ địch ở gần trong một khu vực trong thời gian {b.towers.tree.skill_a.blind.duration[2]} giây, đồng thời giảm sát thương của chúng đi {b.towers.tree.skill_a.blind.s_damage_factor}% trong {b.towers.tree.skill_a.blind.duration[2]} giây.",

  ["Sneezes dealing {b.towers.tree.skill_a.blind.s_damage[3]} true damage to nearby enemies in an area over the course of {b.towers.tree.skill_a.blind.duration[3]} seconds, also reducing their damage by {b.towers.tree.skill_a.blind.s_damage_factor}% for {b.towers.tree.skill_a.blind.duration[3]} seconds."] = "Hắt hơi, gây sát thương chuẩn {b.towers.tree.skill_a.blind.s_damage[3]} cho kẻ địch ở gần trong một khu vực trong thời gian {b.towers.tree.skill_a.blind.duration[3]} giây, đồng thời giảm sát thương của chúng đi {b.towers.tree.skill_a.blind.s_damage_factor}% trong {b.towers.tree.skill_a.blind.duration[3]} giây.",

  ["Sneezes stunning enemies for {b.heroes.hero_ashbite.skill_b.stun_duration} seconds and leaving embers that deal {b.heroes.hero_ashbite.skill_b.burn.s_damage} true damage over {b.heroes.hero_ashbite.skill_b.embers_duration} seconds."] = "Hắt hơi làm choáng kẻ địch trong {b.heroes.hero_ashbite.skill_b.stun_duration} giây và để lại Ember gây sát thương chuẩn cho {b.heroes.hero_ashbite.skill_b.burn.s_damage} trong {b.heroes.hero_ashbite.skill_b.embers_duration} giây.",

  ["Sneezes stunning enemies for {b.heroes.hero_ashbite.upgrades.upg_sb1.stun_duration} seconds and leaving embers that deal {b.heroes.hero_ashbite.upgrades.upg_sb1.s_damage} true damage over {b.heroes.hero_ashbite.upgrades.upg_sb1.embers_duration} seconds."] = "Hắt hơi làm choáng kẻ địch trong {b.heroes.hero_ashbite.upgrades.upg_sb1.stun_duration} giây và để lại Ember gây sát thương chuẩn cho {b.heroes.hero_ashbite.upgrades.upg_sb1.s_damage} trong {b.heroes.hero_ashbite.upgrades.upg_sb1.embers_duration} giây.",

  ["Sneezes stunning enemies for {b.heroes.hero_ashbite.upgrades.upg_sb2.stun_duration} seconds and leaving embers that deal {b.heroes.hero_ashbite.upgrades.upg_sb2.s_damage} true damage over {b.heroes.hero_ashbite.upgrades.upg_sb2.embers_duration} seconds."] = "Hắt hơi làm choáng kẻ địch trong {b.heroes.hero_ashbite.upgrades.upg_sb2.stun_duration} giây và để lại Ember gây sát thương chuẩn cho {b.heroes.hero_ashbite.upgrades.upg_sb2.s_damage} trong {b.heroes.hero_ashbite.upgrades.upg_sb2.embers_duration} giây.",

  ["Snipe 50 enemies."] = "Bắn tỉa 50 kẻ địch.",

