  ["Teleport Scroll"] = "Cuộn dịch chuyển",

  ["Teleport a group of enemies back down the path."] = "Dịch chuyển một nhóm kẻ địch trở lại con đường.",

  ["Teleport up to 10 enemies back down the path."] = "Dịch chuyển tối đa 10 kẻ địch trở lại đường đi.",

  ["Teleported enemies are slowed for {b.upgrades.power_teleportation_sigil.l2b.slow_duration} seconds."] = "Kẻ địch bị dịch chuyển sẽ bị làm chậm trong {b.upgrades.power_teleportation_sigil.l2b.slow_duration} giây.",

  ["Teleports %$heroes.hero_witch.ultimate.max_targets[2]%$ enemies backwards, leaving them asleep for %$heroes.hero_witch.ultimate.duration[2]%$ seconds."] = "Dịch chuyển kẻ địch %$heroes.hero_witch.ultimate.max_targets[2]%$ về phía sau, khiến chúng ngủ trong %$heroes.hero_witch.ultimate.duration[2]%$ giây.",

  ["Teleports %$heroes.hero_witch.ultimate.max_targets[3]%$ enemies backwards, leaving them asleep for %$heroes.hero_witch.ultimate.duration[3]%$ seconds."] = "Dịch chuyển kẻ địch %$heroes.hero_witch.ultimate.max_targets[3]%$ về phía sau, khiến chúng ngủ trong %$heroes.hero_witch.ultimate.duration[3]%$ giây.",

  ["Teleports %$heroes.hero_witch.ultimate.max_targets[4]%$ enemies backwards, leaving them asleep for %$heroes.hero_witch.ultimate.duration[4]%$ seconds."] = "Dịch chuyển kẻ địch %$heroes.hero_witch.ultimate.max_targets[4]%$ về phía sau, khiến chúng ngủ trong %$heroes.hero_witch.ultimate.duration[4]%$ giây.",

  ["Teleports a group of enemies a random distance back in the path."] = "Dịch chuyển một nhóm kẻ địch một khoảng cách ngẫu nhiên trở lại đường đi.",

  ["Teleports a group of up to {b.kr1_mode.towers.arcane.teleport.max_count_base} enemies a random distance back down the path every {b.kr1_mode.towers.arcane.teleport.cooldown} seconds."] = "Dịch chuyển một nhóm kẻ địch lên tới {b.kr1_mode.towers.arcane.teleport.max_count_base} một khoảng cách ngẫu nhiên trở lại đường đi mỗi {b.kr1_mode.towers.arcane.teleport.cooldown} mỗi giây.",

  ["Teleports a short distance, evading attacks."] = "Dịch chuyển một khoảng cách ngắn, tránh đòn tấn công.",

  ["Teleports a small number of enemies backwards the path."] = "Dịch chuyển một số lượng nhỏ kẻ địch về phía sau con đường.",

  ["Teleports enemies backwards the path, leaving them asleep for a while."] = "Dịch chuyển kẻ địch về phía sau con đường, khiến chúng ngủ say một lúc.",

  ["Teleports next to a nearby foremost enemy and slashes it three times. Each hit deals {b.heroes.hero_oni.skill_c.damage_min[1]}-{b.heroes.hero_oni.skill_c.damage_max[1]} physical damage and permanently reduces {b.heroes.hero_oni.skill_c.armor_red}% of the enemies' armor."] = "Dịch chuyển đến cạnh kẻ địch đứng đầu gần đó và chém nó ba lần. Mỗi đòn đánh gây sát thương vật lý {b.heroes.hero_oni.skill_c.damage_min[1]}-{b.heroes.hero_oni.skill_c.damage_max[1]} và giảm vĩnh viễn {b.heroes.hero_oni.skill_c.armor_red}% giáp của kẻ địch.",

  ["Teleports next to a nearby foremost enemy and slashes it three times. Each hit deals {b.heroes.hero_oni.upgrades.upg_sc1.damage_min[2]}-{b.heroes.hero_oni.upgrades.upg_sc1.damage_max[2]} physical damage and permanently reduces {b.heroes.hero_oni.upgrades.upg_sc1.armor_red}% of the enemies' armor."] = "Dịch chuyển đến cạnh kẻ địch đứng đầu gần đó và chém nó ba lần. Mỗi đòn đánh gây sát thương vật lý {b.heroes.hero_oni.upgrades.upg_sc1.damage_min[2]}-{b.heroes.hero_oni.upgrades.upg_sc1.damage_max[2]} và giảm vĩnh viễn {b.heroes.hero_oni.upgrades.upg_sc1.armor_red}% giáp của kẻ địch.",

  ["Teleports next to a nearby foremost enemy and slashes it three times. Each hit deals {b.heroes.hero_oni.upgrades.upg_sc1.damage_min[3]}-{b.heroes.hero_oni.upgrades.upg_sc2.damage_max[3]} physical damage and permanently reduces {b.heroes.hero_oni.upgrades.upg_sc2.armor_red}% of the enemies' armor."] = "Dịch chuyển đến cạnh kẻ địch đứng đầu gần đó và chém nó ba lần. Mỗi đòn đánh gây sát thương vật lý {b.heroes.hero_oni.upgrades.upg_sc1.damage_min[3]}-{b.heroes.hero_oni.upgrades.upg_sc2.damage_max[3]} và giảm vĩnh viễn {b.heroes.hero_oni.upgrades.upg_sc2.armor_red}% giáp của kẻ địch.",

  ["Teleports some enemies backwards the path. Base cooldown: 45 seconds."] = "Dịch chuyển một số kẻ địch về phía sau con đường. Thời gian hồi chiêu cơ bản: 45 giây.",

  ["Teleports the enemy closest to the exit to his position, stunning it for 2 seconds."] = "Dịch chuyển kẻ địch gần lối ra nhất về vị trí của hắn, làm choáng hắn trong 2 giây.",

  ["Teleports the enemy closest to the exit to his position, stunning it for 4 seconds."] = "Dịch chuyển kẻ địch gần lối ra nhất về vị trí của hắn, làm choáng hắn trong 4 giây.",

  ["Teleports the enemy closest to the exit to his position, stunning it for 6 seconds."] = "Dịch chuyển kẻ địch gần lối ra nhất về vị trí của hắn, làm choáng hắn trong 6 giây.",

  ["Teleports up to %$towers.elven_stargazers.teleport.max_targets[1]%$ enemies back down the path."] = "Dịch chuyển tối đa kẻ địch %$towers.elven_stargazers.teleport.max_targets[1]%$ trở lại đường đi.",

  ["Teleports up to %$towers.elven_stargazers.teleport.max_targets[2]%$ enemies further back down the path."] = "Dịch chuyển tối đa kẻ địch %$towers.elven_stargazers.teleport.max_targets[2]%$ trở lại đường đi.",

  ["Teleports up to %$towers.elven_stargazers.teleport.max_targets[3]%$ enemies even further back down the path."] = "Dịch chuyển tức thời kẻ địch %$towers.elven_stargazers.teleport.max_targets[3]%$ thậm chí còn lùi xa hơn nữa trên đường đi.",

  ["Teleports when rallying at least 100 units away, like Magnus."] = "Dịch chuyển tức thời khi tập hợp cách xa ít nhất 100 đơn vị, giống như Magnus.",

  ["Tempest Spirit"] = "Tempest Spirit",

